"""What the openai and anthropic SDKs share: both are generated by
Stainless, so their streams and raw-response wrappers have the same shape.

Call modes of one resource method (``create`` / ``parse``):

==============================  =============================================
mode                            what the wrapper does
==============================  =============================================
plain                           reads the returned model, or instruments the
                                returned ``Stream`` in place
``with_raw_response``           the SDK calls the patched method with an
                                ``X-Stainless-Raw-Response`` header (``true``
                                or ``raw``) and gets a response wrapper back.
                                Its ``parse()`` result is cached by the
                                wrapper, so parsing it here (awaiting it for
                                the async client) gives the record usage and
                                hands the caller the very same object later.
``with_streaming_response``     header value ``stream``: the body is unread
                                and belongs to the caller, so it is never
                                read here. The response's ``parse`` and
                                ``close`` are wrapped on the instance: when
                                the caller parses it, the record gets usage
                                (or the returned stream is instrumented);
                                when the caller reads raw bytes instead, the
                                record is emitted at ``close`` with
                                ``token_usage: None`` and a
                                ``capture_limits`` note.
==============================  =============================================
"""

from __future__ import annotations

import functools
import inspect
from typing import Any, Callable, Dict, Optional

from briefcase._logging import get_logger
from briefcase.integrations.providers._base import (
    ProviderCall,
    ProviderInstrumentor,
    StreamState,
    instrument_stream,
    read,
)

logger = get_logger(__name__)

RAW_RESPONSE_HEADER = "X-Stainless-Raw-Response"

LIMIT_STREAM_LAYOUT = (
    "stream object has no assignable '_iterator' in this SDK version; the stream was "
    "returned untouched and not observed"
)
LIMIT_RAW_UNPARSED = "raw response could not be parsed for the record; usage unknown"
LIMIT_STREAMING_UNPARSED = (
    "with_streaming_response: the body was read as raw bytes (not through .parse()), "
    "so usage and finish reason are unknown"
)

InfoFn = Callable[[Any, bool], Dict[str, Any]]
StateFn = Callable[[ProviderCall, Any], StreamState]


def raw_mode(kwargs: dict) -> Optional[str]:
    """``"parse"`` for ``with_raw_response``, ``"stream"`` for
    ``with_streaming_response``, None for a plain call."""
    headers = kwargs.get("extra_headers")
    try:
        value = headers.get(RAW_RESPONSE_HEADER) if headers is not None else None
    except Exception:
        return None
    if not isinstance(value, str):
        return None
    return "stream" if value == "stream" else "parse"


def header(response: Any, name: str) -> Optional[str]:
    """A response header from a stream / raw response, or None."""
    for path in (("response", "headers"), ("headers",)):
        headers = read(response, *path)
        if headers is not None:
            try:
                value = headers.get(name)
            except Exception:
                value = None
            if isinstance(value, str):
                return value
    return None


class Surface:
    """How to read one resource method's results. ``request_id_header`` is
    the provider's request-id response header."""

    def __init__(self, inst: ProviderInstrumentor, *, is_async: bool, info_fn: InfoFn,
                 state_fn: Optional[StateFn], request_id_header: str) -> None:
        self.inst = inst
        self.is_async = is_async
        self.info_fn = info_fn
        self.state_fn = state_fn
        self.request_id_header = request_id_header

    # -- results ----------------------------------------------------------

    def _finish_parsed(self, call: ProviderCall, parsed: Any, streaming: bool,
                       source: Any) -> None:
        """Finish from a parsed model, or instrument a parsed stream."""
        if streaming and self.state_fn is not None:
            request_id = header(parsed, self.request_id_header) or header(
                source, self.request_id_header)
            state = self.state_fn(call, request_id)
            if instrument_stream(parsed, state.on_item, state.on_end,
                                 is_async=self.is_async, proxy=False) is None:
                call.finish({"request_id": request_id, "limits": [LIMIT_STREAM_LAYOUT]},
                            stream={"chunk_count": None, "stream_completed": None})
            return
        call.finish(self.info_fn(parsed, self.inst.captures_content))

    def end(self, call: ProviderCall, result: Any, args: tuple, kwargs: dict) -> Any:
        mode = raw_mode(kwargs)
        streaming = kwargs.get("stream") is True
        if mode is None:
            self._finish_parsed(call, result, streaming, result)
            return result
        call._record["response_wrapper"] = (
            "with_streaming_response" if mode == "stream" else "with_raw_response")
        if mode == "stream":
            self._hook_streaming_response(call, result, streaming)
            return result
        parsed = result.parse()
        if inspect.isawaitable(parsed):
            # An async raw response reached the sync path (should not
            # happen: the async wrapper uses aend). Do not leave a
            # coroutine un-awaited.
            close = getattr(parsed, "close", None)
            if callable(close):
                close()
            call.finish({"request_id": header(result, self.request_id_header),
                         "limits": [LIMIT_RAW_UNPARSED]})
            return result
        self._finish_parsed(call, parsed, streaming, result)
        return result

    async def aend(self, call: ProviderCall, result: Any, args: tuple, kwargs: dict) -> Any:
        mode = raw_mode(kwargs)
        if mode != "parse":
            return self.end(call, result, args, kwargs)
        call._record["response_wrapper"] = "with_raw_response"
        try:
            parsed = result.parse()
            if inspect.isawaitable(parsed):
                parsed = await parsed
        except Exception:
            logger.debug("raw response could not be parsed", exc_info=True)
            call.finish({"request_id": header(result, self.request_id_header),
                         "limits": [LIMIT_RAW_UNPARSED]})
            return result
        self._finish_parsed(call, parsed, kwargs.get("stream") is True, result)
        return result

    # -- with_streaming_response ------------------------------------------

    def _hook_streaming_response(self, call: ProviderCall, response: Any,
                                 streaming: bool) -> None:
        """Wrap ``parse`` and ``close`` on one unread response object."""
        request_id = header(response, self.request_id_header)

        def unparsed() -> None:
            call.finish({"request_id": request_id, "limits": [LIMIT_STREAMING_UNPARSED]})

        def parsed_by_caller(parsed: Any, to: Any) -> None:
            if call.done:
                return
            if to is not None:
                # Parsed into a type of the caller's choosing: not ours to
                # interpret.
                unparsed()
                return
            self._finish_parsed(call, parsed, streaming, response)

        def guarded(fn: Callable[..., None], *a: Any) -> None:
            try:
                fn(*a)
            except Exception:
                logger.debug("streaming response capture failed", exc_info=True)
                call.finish({"request_id": request_id, "limits": [LIMIT_STREAMING_UNPARSED]})

        call.on_abandon(unparsed)
        try:
            original_parse = response.parse
            original_close = response.close
            if inspect.iscoroutinefunction(original_parse):
                @functools.wraps(original_parse)
                async def aparse(*a: Any, **k: Any) -> Any:
                    parsed = await original_parse(*a, **k)
                    guarded(parsed_by_caller, parsed, k.get("to"))
                    return parsed

                @functools.wraps(original_close)
                async def aclose(*a: Any, **k: Any) -> Any:
                    try:
                        return await original_close(*a, **k)
                    finally:
                        guarded(self._closed, call, unparsed)

                response.parse = aparse
                response.close = aclose
            else:
                @functools.wraps(original_parse)
                def parse(*a: Any, **k: Any) -> Any:
                    parsed = original_parse(*a, **k)
                    guarded(parsed_by_caller, parsed, k.get("to"))
                    return parsed

                @functools.wraps(original_close)
                def close(*a: Any, **k: Any) -> Any:
                    try:
                        return original_close(*a, **k)
                    finally:
                        guarded(self._closed, call, unparsed)

                response.parse = parse
                response.close = close
        except Exception:
            logger.debug("streaming response could not be hooked", exc_info=True)
            unparsed()

    @staticmethod
    def _closed(call: ProviderCall, unparsed: Callable[[], None]) -> None:
        """The caller closed the response. A stream parsed out of it reports
        its own end (as incomplete, if it was not read through); anything
        else was never parsed."""
        if call.done:
            return
        abandon = call._abandon
        if abandon is not None and abandon is not unparsed:
            abandon()
        else:
            unparsed()


__all__ = [
    "LIMIT_RAW_UNPARSED",
    "LIMIT_STREAMING_UNPARSED",
    "LIMIT_STREAM_LAYOUT",
    "RAW_RESPONSE_HEADER",
    "Surface",
    "header",
    "raw_mode",
]
